# -*- coding: utf-8 -*-
"""Великобритания: события EVENTS_C, новости NEWS_C, региональные события REG_EVENTS."""

_G = {"W": "Рабочие", "B": "Бизнес", "P": "Пенсионеры", "Y": "Молодёжь", "S": "Бюджетники", "R": "Село", "F": "Силовики", "E": "Экологи"}


def s(**kw):
    return {_G[k]: float(v) for k, v in kw.items()}


def _g(v):
    return ("%g" % v)


def o(l, **fx):
    """Вариант ответа; подпись автоматически дополняется ценой (капитал / долг / ползунок)."""
    out = {}
    for k, v in fx.items():
        out[k] = float(v) if isinstance(v, (int, float)) else v
    extra = []
    if "capital" in out and out["capital"] < 0:
        extra.append("капитал %s" % _g(out["capital"]))
    if "debt" in out and out["debt"] != 0:
        extra.append("долг %s%% ВВП" % ("+" + _g(out["debt"]) if out["debt"] > 0 else _g(out["debt"])))
    if "slider" in out:
        for kk, vv in out["slider"].items():
            extra.append("%s%s%% ВВП" % ("+" if vv > 0 else "", _g(vv)))
            break
    if extra:
        l = "%s (%s)" % (l, ", ".join(extra))
    return {"l": l, "fx": out}


def ev(t, opts, reg=None, cond=None):
    e = {"t": t, "o": opts}
    if reg:
        e["reg"] = reg
    if cond:
        e["cond"] = cond
    return e


